        if not inb(nx, ny) or (nx, ny) in blocks:
            continue
        sc = 0
        if (nx, ny) in unclaimed:
            sc += 50
        if (nx, ny) in self_terr:
            sc -= 5
        if (nx, ny) in opp_terr:
            sc -= 100
        near_opp = any(c in opp_terr for c in adj8(nx, ny))
        near_self = any(c in self_terr for c in adj8(nx, ny))
